//迭代法
class Solution { public:
vector inorderTraversal(TreeNode root) {
   vector ans;
   stack stk;
   TreeNode* curr = root;
   while(!stk.empty() || curr != NULL) {
// 找到节点的最左侧节点，同时记录路径入栈 while(curr != NULL) {       stk.push(curr);
       curr = curr->left;
   }
// top 定义是此刻的弹栈元素 TreeNode* top = stk.top(); ans.push_back(top->val); stk.pop();
// 处理过最左侧结点后，判断其是否存在右子树 if(top->right != NULL)       curr = top->right;
   return ans;
} };
}
LeetCode 145. 二叉树的后序遍历
难度简单630 给定一个二叉树，返回它的 后序 遍历。 示例:
输入: [1,null,2,3] 1
\ 2
/ 3
输出: [3,2,1]
进阶: 递归算法很简单，你可以通过迭代算法完成吗? 【思路】
1、前序遍历的过程是中左右。 2、将其转化成中右左。也就是压栈的过程中优先压入左子树，再压入右子树。 3、在弹栈的同时将此弹栈结点压入另一个栈，完成逆序。 4、对新栈中的元素直接顺序弹栈并输出。
【代码】
/**


Definition for a binary tree node.
struct TreeNode {
int val;


TreeNode *left;
TreeNode *right;
TreeNode() : val(0), left(nullptr), right(nullptr) {}
TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
TreeNode(int x, TreeNode left, TreeNode right) : val(x), left(left),
right(right) {}
};
/ /
//递归版
class Solution { public:
 vector ans;
 vector preorderTraversal(TreeNode root) {
// 为空则直接返回 if(root == NULL)
return ans;
 } };
preorderTraversal(root->left);
preorderTraversal(root->right);
ans.push_back(root->val);
return ans;
/
//非递归版
class Solution { public:
 std::vector postorderTraversal(TreeNode* root) { std::vector res;
 if (!root) return res;
 std::stack st1;
std::stack st2; st1.push(root);
// 栈一顺序存储
while (!st1.empty()){     TreeNode* node = st1.top();
     st1.pop();
     st2.push(node);
     if (node->left) st1.push(node->left);
     if (node->right) st1.push(node->right);
}
// 栈二直接输出
while (!st2.empty()) {     res.push_back(st2.top()->val);
st2.pop(); }
return res; }
