private boolean draw(boolean fullRedrawNeeded) {
    Surface surface = mSurface;
    // ...
    if (!drawSoftware(surface, mAttachInfo, xOffset, yOffset, scalingRequired, dirty, surfaceInsets)) {
        return false;
    }
